\text { rere, } \quad \begin{aligned}
M_{u x} & =\frac{r^{4}}{8\left(1+r^{4}\right)} w \ell_{x}^{2} \\
M_{u y} & =\frac{r^{2}}{8\left(1+r^{4}\right)} w \ell_{x}^{2} \\
\text { Her } & =\frac{\ell_{y}}{\ell_{x}} \\
\Rightarrow \quad \frac{M_{u x}}{M_{u y}} & =r^{2}=\left(\frac{\ell_{y}}{\ell_{x}}\right)^{2}
\end{aligned}

\begin{aligned}
& A_{s t}(\text { in } \%)=\frac{A_{s t}}{B \cdot d} \times 100 \\
& \Rightarrow \quad 0.2=\frac{\left(n \times \frac{\pi}{4} \phi^{2}\right) \times 100}{\text { B.d }} \\
& \Rightarrow \quad \frac{0.2}{100}=\frac{\left(\frac{B}{S}\right) \times \frac{\pi}{4} \times 8^{2}}{B \times 250} \\
& \Rightarrow \quad S=\frac{\frac{\pi}{4} \times 8^{2} \times 100}{0.2 \times 250} \\
& S=100.53 \mathrm{~mm}
\end{aligned}

\begin{aligned}
P & =\text { Prestressing force } \\
e & =\text { Eccentricity of P-force } \\
M_{c r} & =\text { cracking moment for beam B1 }
\end{aligned}

\begin{aligned}
\frac{M_{c r}}{I} y_{b} & =\frac{P}{A}+\frac{P e y_{t}}{I} \\
\Rightarrow \quad M_{c r} & =\frac{P I}{A y_{b}}+P e \\
& =\frac{P e y_{t}}{y_{b}}+P e \\
& =\frac{P e(2 H / 3)}{(H / 3)}+P e \\
& =3 P e=3 \times 1000 \times \frac{100}{1000}=300 \mathrm{kNm}
\end{aligned}

